class Ra2GarrisonRepairGateTest2{[DllImport("kernel32.dll")]static extern IntPtr OpenProcess(uint a,bool b,int p);[DllImport("kernel32.dll")]static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr r);[DllImport("kernel32.dll")]static extern bool WriteProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr w);static void Main(string[]x){bool off=x.Length==1&&x[0]=="--off";var g=Process.GetProcessesByName("game")[0];IntPtr h=OpenProcess(0x438,false,g.Id);IntPtr a=new IntPtr(0x0044D8EB);byte[]cur=new byte[2];IntPtr n;if(!ReadProcessMemory(h,a,cur,2,out n)){Console.WriteLine("READ_FAILED");return;}byte[]want=off?new byte[]{0x74,0x04}:new byte[]{0x90,0x90};if(!off&&(cur[0]!=0x74||cur[1]!=0x04)){Console.WriteLine("PATCH_MISMATCH {0:X2} {1:X2}",cur[0],cur[1]);return;}if(off&&(cur[0]!=0x90||cur[1]!=0x90)){Console.WriteLine("NOT_PATCHED");return;}IntPtr w;if(WriteProcessMemory(h,a,want,2,out w)&&w.ToInt64()==2)Console.WriteLine("GARRISON_REPAIR_GATE_{0}",off?"RESTORED":"BYPASSED");else Console.WriteLine("WRITE_FAILED");}}
